long start = System.currentTimeMillis();
try {
    paymentGateway.charge(order);
    long duration = System.currentTimeMillis() - start;
    log.info("payment_processed order_id={} duration_ms={} status=OK", order.id(), duration);
} catch (PaymentException e) {
    log.error("payment_failed order_id={} reason={}", order.id(), e.getMessage());
}

